// Verifies the HMAC signature Convex puts on every webhook.
// Secret comes from the environment (LENDLOOP_WEBHOOK_SECRET); comma-separated values allow rotation.
const crypto = require('crypto');
const secrets = ($env.LENDLOOP_WEBHOOK_SECRET || '').split(',').map(s => s.trim()).filter(Boolean);
const item = $input.first();
const h = item.json.headers || {};
const ts = String(h['x-lendloop-timestamp'] || '');
const sig = String(h['x-lendloop-signature'] || '');

// Prefer the exact raw bytes; fall back to the parsed body (Convex sends compact JSON.stringify output).
let raw = null;
try {
  if (item.binary && item.binary.data) raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} catch (e) { raw = null; }
const candidates = [raw, JSON.stringify(item.json.body)].filter(Boolean);

const fresh = /^\d{9,11}$/.test(ts) && Math.abs(Date.now() / 1000 - Number(ts)) <= 300; // 5-minute replay window
const m = /^v1=([0-9a-f]{64})$/.exec(sig);
let valid = false;
if (secrets.length && fresh && m) {
  const given = Buffer.from(m[1], 'hex');
  for (const s of secrets) {
    for (const body of candidates) {
      const expected = crypto.createHmac('sha256', s).update(`${ts}.${body}`).digest();
      if (expected.length === given.length && crypto.timingSafeEqual(expected, given)) valid = true;
    }
  }
}

// Headers and raw body stop here; only the verified event moves on.
return [{ json: { valid, event: valid ? item.json.body : null } }];

// Turns the minimal Convex event into an email. User-typed text is HTML-escaped.
const e = $input.first().json.event;
const appUrl = ($env.LENDLOOP_APP_URL || 'http://localhost:3100').replace(/\/$/, '');
const from = $env.NOTIFY_FROM || 'LendLoop <onboarding@resend.dev>';
const override = ($env.NOTIFY_OVERRIDE_TO || '').trim(); // dev only: no verified Resend domain
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fmt = iso => new Date(iso + 'T00:00:00Z').toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' });
const range = e.startDate === e.endDate ? fmt(e.startDate) : `${fmt(e.startDate)} to ${fmt(e.endDate)}`;
const who = e.otherPartyName, tool = e.toolName;

const copy = {
  requested: [`${who} wants to borrow your ${tool}`, `${who} asked to borrow your ${tool} for ${range}.`, e.note ? `Their note: "${e.note}"` : '', 'Approve or decline'],
  approved: [`Approved: ${tool}`, `${who} approved your request to borrow the ${tool} for ${range}.`, `Please bring it back by ${fmt(e.endDate)}.`, 'See your loan'],
  declined: [`Not this time: ${tool}`, `${who} can't lend the ${tool} for ${range}.`, 'Have a look on the board for another one nearby.', 'Browse the shelf'],
  cancelled: [`Cancelled: ${tool} (${range})`, `${who} no longer needs your ${tool} for ${range}, so the request or booking is cancelled.`, 'Those dates are free again.', 'Open LendLoop'],
  booking_cancelled: [`Booking cancelled: ${tool}`, `${who} had to cancel your booking of the ${tool} for ${range}.`, 'Have a look on the board for another one nearby.', 'Browse the shelf'],
  returned: [`Returned: ${tool}`, `${who} marked the ${tool} as returned.`, 'Thanks for borrowing responsibly.', 'Open LendLoop'],
  tool_removed: [`No longer available: ${tool}`, `The ${tool} listing was removed, so your request for ${range} was cancelled.`, '', 'Browse the shelf'],
}[e.event];
if (!copy) throw new Error(`Unknown event type: ${e.event}`);
const [subject, line1, line2, cta] = copy;
const link = `${appUrl}${['declined', 'tool_removed', 'booking_cancelled'].includes(e.event) ? '/board' : '/requests'}`;
const to = override || e.recipient.email;

const html = `<div style="font-family:system-ui,sans-serif;max-width:520px;color:#18181b">` +
  (override ? `<p style="font-size:12px;color:#6b6b74">Dev mode: intended for ${esc(e.recipient.email)}</p>` : '') +
  `<p>Hi ${esc(e.recipient.name)},</p><p>${esc(line1)}</p>` + (line2 ? `<p>${esc(line2)}</p>` : '') +
  `<p><a href="${link}" style="display:inline-block;background:#18181b;color:#fff;padding:10px 16px;border-radius:8px;text-decoration:none">${esc(cta)}</a></p>` +
  `<p style="font-size:12px;color:#6b6b74">LendLoop. Borrow what you need. Lend what you don't.</p></div>`;
const text = [`Hi ${e.recipient.name},`, line1, line2, `${cta}: ${link}`].filter(Boolean).join('\n\n');

return [{ json: {
  loanId: e.loanId,
  idempotencyKey: e.eventId,
  resend: { from, to: [to], subject: override ? `[for ${e.recipient.email}] ${subject}` : subject, html, text },
} }];

// Signs the write-back to Convex with LENDLOOP_API_SECRET (from the environment).
const crypto = require('crypto');
const secret = ($env.LENDLOOP_API_SECRET || '').split(',')[0].trim();
if (!secret) throw new Error('LENDLOOP_API_SECRET is not set');
const src = $('Build email').item.json;
const body = JSON.stringify({ loanId: src.loanId, kind: 'notification_sent', idempotencyKey: `notify:${src.idempotencyKey}` });
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
return { json: { body, timestamp, signature } };

const crypto = require('crypto');
const secret = ($env.LENDLOOP_API_SECRET || '').split(',')[0].trim();
if (!secret) throw new Error('LENDLOOP_API_SECRET is not set');
const src = $('Build email').item.json;
const body = JSON.stringify({ loanId: src.loanId, kind: 'notification_failed', idempotencyKey: `notify-failed:${src.idempotencyKey}:${$execution.id}`, detail: 'email provider error' });
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
return { json: { body, timestamp, signature, error: $json.error?.message || 'Resend request failed' } };
